import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"{% content %} - October CMS - 3.x","titleTemplate":false,"description":"Twig 标签","frontmatter":{"subtitle":"Twig 标签"},"headers":[{"level":2,"title":"变量","slug":"变量","link":"#变量","children":[]},{"level":2,"title":"将内容设置为 Twig 变量","slug":"将内容设置为-twig-变量","link":"#将内容设置为-twig-变量","children":[]},{"level":2,"title":"检查内容文件是否存在","slug":"检查内容文件是否存在","link":"#检查内容文件是否存在","children":[]},{"level":2,"title":"将内容解析为字符串","slug":"将内容解析为字符串","link":"#将内容解析为字符串","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/markup/tag/content.md","filePath":"3.x/zh-cn/markup/tag/content.md"}'),u={name:"3.x/zh-cn/markup/tag/content.md"};function g(r,n,k,d,m,w){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"{% content %}",-1)),s(e),n[1]||(n[1]=i(`<p><code>{% content %}</code> 标签将在页面上显示一个 <a href="./../../cms/themes/content.html">CMS 内容块</a>。要显示名为 <strong>contacts.htm</strong> 的内容块，在 <code>content</code> 标签后以引号字符串的形式传递文件名即可。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>contacts.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>子目录中的内容块也可以用同样的方式渲染。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/content.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../cms/themes/themes.html">主题文档</a>有更多关于子目录用法的详细信息。</p></div><p>内容块可以渲染为纯文本：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>readme.txt<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>你也可以使用 Markdown 语法：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>changelog.md<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>内容块还可以与<a href="./../../cms/themes/layouts.html">布局占位符</a>结合使用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> sidebar <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>sidebar-content.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="变量"><a href="#变量" class="header-anchor">#</a> 变量</h2><p>你可以在文件名后指定变量来向内容块传递变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> name<span class="token operator">=</span>user<span class="token punctuation">.</span>name <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>你也可以为内容分配新的变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>location.htm<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在内容内部，可以使用单<em>花括号</em>的基本语法访问变量：</p><div class="language- extra-class"><pre class="language-text"><code>&lt;p&gt;Country: {country}, city: {city}.&lt;/p&gt;
</code></pre></div><p>你也可以将变量集合作为简单数组传递：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> likes<span class="token operator">=</span><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Dogs<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Fishing<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Golf<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span>
<span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>变量集合通过使用一对开闭括号来访问：</p><div class="language- extra-class"><pre class="language-text"><code>&lt;ul&gt;
    {likes}
        &lt;li&gt;{name}&lt;/li&gt;
    {/likes}
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>注意</strong>：内容块不支持 Twig 语法，请考虑使用 <a href="./../cms/partials.html">CMS 部件</a>代替。</p></blockquote><h2 id="将内容设置为-twig-变量"><a href="#将内容设置为-twig-变量" class="header-anchor">#</a> 将内容设置为 Twig 变量</h2><p>在任何模板中，你可以使用 <code>content()</code> 函数将内容设置为变量。这允许你在显示之前操作输出。记得使用 <code>|raw</code> 过滤器来防止输出转义。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> welcomeContent<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>你也可以将变量作为第二个参数传递给内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="检查内容文件是否存在"><a href="#检查内容文件是否存在" class="header-anchor">#</a> 检查内容文件是否存在</h2><p><code>hasContent()</code> 函数可用于检查内容是否存在而不渲染内容。要阻止内容的渲染，将第二个参数设置为 false，如果找到内容文件则返回 true，否则返回 false。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasContent<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome content not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="将内容解析为字符串"><a href="#将内容解析为字符串" class="header-anchor">#</a> 将内容解析为字符串</h2><p>使用 <code>{% content %}</code> 标签时，它会自动解析 <a href="./../../cms/themes/snippets.html">CMS 代码片段</a>和<a href="./../../element/form/widget-pagefinder.html">页面查找器表单小部件</a>创建的链接。</p><p>类似地，<code>|content</code> 过滤器可用于解析 HTML 字符串中的多个内容对象并在输出中解析它们。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>content<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p><code>|md</code> 过滤器也可用于解析字符串中的 Markdown 内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>markdown_content<span class="token operator">|</span>md<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../cms/themes/snippets.html">CMS 代码片段</a></li><li><a href="./../../markup/filter/link.html">Link Twig 过滤器</a></li><li><a href="./../../markup/filter/md.html">Markdown Twig 过滤器</a></li></ul></div>`,39))])}const f=p(u,[["render",g]]);export{v as __pageData,f as default};
